import {TODAY,STORAGE,NAV,uid,clone,createState,nutrition,target,mealsOn,dayTotals,portionLines,saveMeal,addShortages,toggleIntake,shiftDate,load} from './model.mjs';
let state=load(localStorage), date=TODAY, route='diary', params=new URLSearchParams(), portion=1, cookStep=0;
let draft=null, recipeDraft=null, lastTab='diary', toastTimer, undoAction=null;
const searchTerms=new Map(), contextDates=new Map();
const scrolls=new Map(), main=document.querySelector('#main'), dialog=document.querySelector('#dialog');
const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=0)=>Number(v||0).toLocaleString('hu-HU',{maximumFractionDigits:d});
const I=(name,size=28)=>`<svg class="clay" width="${size}" height="${size}" aria-hidden="true"><use href="./assets/clay-icons.svg#i-${name}"/></svg>`;
const orb=(tone='sage',size='')=>`<span class="orb ${tone} ${size}" aria-hidden="true"><i></i><i></i></span>`;
const B=(text,action,cls='button',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,to,cls='text-btn')=>`<button type="button" class="${cls}" data-go="${h(to)}">${text}</button>`;
const title=(eyebrow,text,sub='')=>`<div class="page-title"><p class="eyebrow">${eyebrow}</p><h1 tabindex="-1">${text}</h1>${sub?`<p>${sub}</p>`:''}</div>`;
const heading=(text,action='')=>`<div class="section-heading"><h2>${text}</h2>${action}</div>`;
const empty=(text,action='')=>`<div class="empty">${I('recept',64)}<h2>${text}</h2>${action}</div>`;
const field=(label,name,value='',type='text',attr='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${h(value)}" ${attr}></label>`;
const select=(label,name,value,options)=>`<label class="field">${label}<select name="${name}">${options.map(v=>`<option ${v===value?'selected':''}>${h(v)}</option>`).join('')}</select></label>`;
const row=(icon,label,sub,to,right='')=>`<button class="nav-row" data-go="${h(to)}">${I(icon,38)}<span><strong>${label}</strong><small>${sub}</small></span><b>${right||'↗'}</b></button>`;
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{notify('A böngészőben most nem sikerült menteni.');}}
function notify(message,undo){if(dialog.open){let feedback=dialog.querySelector('.modal-feedback');if(!feedback){feedback=document.createElement('p');feedback.className='modal-feedback';feedback.setAttribute('role','status');dialog.querySelector('.dialog-body').prepend(feedback);}feedback.textContent=message;}undoAction=undo||null;const t=document.querySelector('#toast');t.innerHTML=`${h(message)} ${undo?B('Visszavonás','undo','text-btn'):''}`;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),6500);}
function go(to){scrolls.set(location.hash,main.scrollTop);if(dialog.open)dialog.close();const next='#'+to;if(location.hash===next){render();return;}const from=location.hash;location.hash=next;history.replaceState({fuelLab:true,from},'');}
function getRecipe(){return state.recipes.find(r=>r.id===params.get('id'));}
function getMeal(){return state.meals.find(m=>m.id===params.get('id'));}
function missing(){return empty('Ezt a tételt már nem találom.',link('Vissza a naplóhoz','diary','button'));}
function startMeal(lines=[],name='',slot='Ebéd',source='Kézi'){
 draft={name,slot,date,time:'13:40',icon:slot==='Reggeli'?'reggeli':slot==='Vacsora'?'vacsora':slot==='Kisétkezés'?'snack':'ebed',source,lines:clone(lines)};state.draft=draft;persist();go('log');
}
function macros(t,goals=false){return `<div class="macros">${[['p','Fehérje','coral'],['c','Szénhidrát','gold'],['f','Zsír','lavender'],['fiber','Rost','sage']].map(([k,label,tone])=>`<div class="macro ${tone}"><span>${label}</span><strong>${n(t[k])}<small> g</small></strong>${goals?`<div class="track"><i style="width:${Math.min(100,100*t[k]/state.settings[k])}%"></i></div><small>${n(state.settings[k])} g cél</small>`:''}</div>`).join('')}</div>`;}
function statLine(t){return `<div class="nutrition-line"><strong>${n(t.kcal)} <small>kcal</small></strong><span>${n(t.p)} g P</span><span>${n(t.c)} g CH</span><span>${n(t.f)} g Zs</span></div>`;}
function dateLabel(d){return new Date(d+'T12:00:00').toLocaleDateString('hu-HU',{month:'long',day:'numeric'});}
function dayPicker(){const last=route==='plan'?'2026-09-13':TODAY;return `<div class="day-picker">${B('‹','day-prev','round','aria-label="Előző nap"')}<label><span>${date===TODAY?'Ma · ':''}${dateLabel(date)}</span><input aria-label="Napló napja" id="date-picker" type="date" value="${date}" min="2026-09-02" max="${last}"></label>${B('›','day-next','round',`aria-label="Következő nap" ${date>=last?'disabled':''}`)}${link('Hét ↗','week','pill')}</div>`;}
function mealRow(m){const t=nutrition(m.lines,state.pantry);return `<div class="meal-row"><button class="meal-main" data-go="meal?id=${m.id}"><span class="meal-icon ${m.icon}">${I(m.icon,46)}</span><span><small>${h(m.time)} · ${h(m.slot)}</small><strong>${h(m.name)}</strong><span class="meal-meta">${n(t.kcal)} kcal <i>·</i> ${n(t.p)} g fehérje</span></span></button>${link(`<span class="score-star">✧</span> ${m.score}`,'score?id='+m.id,'score-chip')}</div>`;}
function diary(){const t=dayTotals(state,date),goal=target(state),meals=mealsOn(state,date);const avg=meals.length?Math.round(meals.reduce((a,m)=>a+m.score,0)/meals.length):null;const nextSlot=state.slots.find(s=>!meals.some(m=>m.slot===s.name));
 return `<div class="diary-title-row">${title('TÁPLÁLÁS','A napod, <em>jó alapokon.</em>')}${B('+','new-meal','quick-meal','aria-label="Étkezés hozzáadása"')}</div>${dayPicker()}
 <section class="energy-card"><div class="energy-orbits"></div><div class="energy-top"><span class="eyebrow">ELFOGYASZTVA</span>${link('A kereted ↗','energy','quiet-link')}</div><div class="energy-values"><div><strong class="hero-number">${n(t.kcal)}</strong><span class="unit">kcal</span><p>${n(goal-t.kcal)} kcal ${goal>=t.kcal?'maradt a keretedből':'a kerethez képest'}</p></div><button class="energy-ring" data-go="energy" style="--progress:${Math.min(100,t.kcal/goal*100)}%" aria-label="Napi energiakeret részletei"><span>${n(t.kcal/goal*100)}<small>%</small></span></button></div><div class="energy-foot"><span>Mai keret <b>${n(goal)}</b> kcal</span><span>${I('edzes',18)} Mozgás +${n(state.settings.movement)}</span></div></section>
 ${macros(t,true)}<div class="water-strip">${B(`${I('viz',22)} <b>${n((state.water[date]||0)/1000,2)}</b><span>/ ${n(state.settings.water/1000,1)} l víz</span>`,'water','water-button')}${B('+ 250 ml','water-add','pill blue')}</div>
 ${heading('Az étkezéseid',B('+ Rögzítés','new-meal','text-btn accent'))}<div class="meal-list">${meals.length?meals.map(mealRow).join(''):empty('Még tiszta lap.',B('Az első étkezésem','new-meal','button'))}</div>
 ${date===TODAY&&nextSlot?`<section class="next-meal"><div class="next-copy"><p class="eyebrow">KÖVETKEZŐ ABLAK · ${h(nextSlot.time)}</p><h3>Mi esne jól <em>estére?</em></h3><p>A kamrádból is indulhatunk.</p>${link('Vacsoraötletek ↗','recipes?category=Vacsora','text-btn')}</div>${I('vacsora',86)}</section>`:''}
 ${avg?`<button class="day-score" data-go="week"><div>${I('minta',34)}<span><strong>A napod összképe</strong><small>${meals.length} étkezés · részletes értékeléssel</small></span></div><b>${avg}<small> AI score ↗</small></b></button>`:''}
 ${row('heti','A hét ritmusa','Étkezési terv és időzítés','plan')}${row('stack','A kiegészítőid','Következő bevétel és napi ritmus','stack')}
 <p class="demo-note">Szemléltető mintanap · az AI score demonstráció.</p>`;
}
function energy(){const s=state.settings;return `${title('A KERETED HÁTTERE','Több szál.<br><em>Egy napi keret.</em>','A mozgásod és a célod ugyanabban a képben.')}
 <div class="energy-card large-number"><p class="eyebrow">NAPI ENERGIAKERET</p><strong>${n(target(state))}<small> kcal</small></strong>${I('fuel',70)}</div>
 <div class="equation">${row('eletjel','Alapkeret','A mintaprofilból','settings-goals',n(s.base))}${row('edzes','Mai mozgás','Edzés a mintanapban','movement','+'+n(s.movement))}${row('cel','Célod hatása','A mentett mintabeállítás','settings-goals',n(s.balance))}</div>
 <div class="companion-note">${orb()}<div><strong>A keret együtt mozog a napoddal.</strong><p>A mozgás változását itt is követheted. A naplózott étkezéseid közben megmaradnak.</p>${B('Beszéljük át','chat','text-btn')}</div></div>${macros(state.settings)}<p class="demo-note">Szemléltető számítás, nem személyre szabott táplálkozási előírás.</p>`;}
function week(){const days=Array.from({length:7},(_,i)=>shiftDate('2026-09-07',i));const all=state.meals.filter(m=>days.includes(m.date)),avg=all.length?Math.round(all.reduce((a,m)=>a+m.score,0)/all.length):0;
 return `${title('NAPLÓ / HETI NÉZET','Az apró részletek<br><em>összeérnek.</em>','Szeptember 7–13. · a mintahét')}
 <div class="week-hero"><p class="eyebrow">ÉTKEZÉSI AI SCORE</p><strong>${avg||'—'}<small> / 100</small></strong><p>${all.length} rögzített étkezésből</p></div>${heading('A hét energiája','<small>kcal / nap</small>')}<div class="week-chart">${days.map((d,i)=>{let t=dayTotals(state,d);return `<button data-action="select-day" data-date="${d}" ${d>TODAY?'disabled':''}><span>${t.kcal?n(t.kcal):'—'}</span><div><i style="height:${Math.min(100,t.kcal/target(state)*100)}%"></i></div><strong>${['H','K','Sze','Cs','P','Szo','V'][i]}</strong><small>${d.slice(-2)}</small></button>`;}).join('')}</div><p class="caption">A hiányzó nap nem nulla bevitel. A keret magassága ${n(target(state))} kcal.</p>
 ${heading('Napok és részletek')}${days.filter(d=>d<=TODAY).reverse().map(d=>row('naplo',dateLabel(d),`${mealsOn(state,d).length} étkezés · ${n(dayTotals(state,d).kcal)} kcal`,'diary?date='+d)).join('')}${row('heti','A következő napok terve','Ritmus, étkezések és receptek','plan')}`;
}
function mealDetail(){const m=getMeal();if(!m)return missing();const t=nutrition(m.lines,state.pantry);return `${title(`${h(m.slot).toUpperCase()} · ${h(m.time)}`,h(m.name),dateLabel(m.date))}<div class="dish-hero sage">${I(m.icon,112)}<span>${n(t.kcal)}<small> kcal</small></span></div>${macros(t)}<button class="score-feature" data-go="score?id=${m.id}"><div><p class="eyebrow">AZ ÉTKEZÉSED AI SCORE-JA</p><h2>Értsd is a számot.</h2><p>8 nézőpont · forrásokkal és részletekkel</p></div><strong>${m.score}<small>/ 100 ↗</small></strong></button>${heading('Ami belekerült',B('Szerkesztés','edit-meal','text-btn'))}${m.lines.map(l=>{let p=state.pantry.find(x=>x.id===l.id);return row(p?.icon||'kamra',h(p?.name||'Törölt tétel'),`${n(l.g)} g · ${n(nutrition([l],state.pantry).kcal)} kcal`,'item?id='+l.id);}).join('')}<p class="caption">Forrás: ${h(m.source)} · a mennyiségek szerkeszthetők.</p><div class="action-pair">${B('Étkezés javítása','edit-meal','button')}${B('Törlés','delete-meal','button secondary')}</div>`;}
function score(){const m=getMeal();if(!m)return missing();const labels=['Fehérje','Energiailleszkedés','Rost','Zsírminőség','Feldolgozottság','Mikrotápanyagok','Időzítés','Napi összhang'];const offsets=[-4,3,1,-2,2,-1,4,-3];return `${title('ÉTKEZÉSI ÉRTÉKELÉS','A szám mögött<br><em>ott a részlet.</em>',h(m.name))}<section class="score-hero"><div class="score-circle"><strong>${m.score}</strong><span>AI SCORE / 100</span></div><h2>Jó alapok ebben az étkezésben.</h2><p>A tápanyagok, az összetétel és a napod összefüggései együtt jelennek meg.</p><span class="badge">Szemléltető értékelés</span></section>${heading('Miből áll össze?','<small>8 nézőpont</small>')}<div class="dimensions">${labels.map((label,i)=>`<details class="dimension ${['coral','gold','sage','lavender'][i%4]}"><summary><span>${label}<small>12,5% súly</small></span><b>${m.score+offsets[i]} <small>⌄</small></b><div class="track"><i style="width:${m.score+offsets[i]}%"></i></div></summary><p>${i===0?`${n(nutrition(m.lines,state.pantry).p)} g fehérje szerepel a megadott hozzávalókban.`:'Az értékelés ezen nézőpontja a részletes bontás elrendezését szemlélteti.'} A pontszám előre megadott demóérték.</p><span class="caption">Hozzájárulás: ${n((m.score+offsets[i])/8,1)} / 12,5 pont</span></details>`).join('')}</div>${heading('És hogyan tovább?')}<div class="companion-note">${orb('lavender')}<div><strong>A részletekből indulhatunk.</strong><p>Átnézhetjük a mennyiségeket, vagy alakíthatunk a következő étkezésen.</p>${B('Beszéljük át','chat','text-btn')}${B('Mennyiségek javítása','edit-meal','text-btn')}</div></div><details class="plain-details"><summary>Források és bizonytalanság ⌄</summary><p>A grammokból számolt makrók a szerkeszthető mintakamrából jönnek. A nyolc részpont és a szöveges AI értékelés demó: itt nem fut a valódi pontozómotor vagy AI.</p></details>${B('Újraértékelés kipróbálása','rescore','button secondary')}`;}
function lineEditor(lines,kind='meal'){return lines.map((l,i)=>{const p=state.pantry.find(x=>x.id===l.id);return `<div class="ingredient-edit">${I(p?.icon||'kamra',30)}<span><strong>${h(p?.name)}</strong><small>${n(p?.kcal)} kcal / 100 g</small></span><label><input aria-label="${h(p?.name)} gramm" type="number" min="1" max="10000" step="1" value="${l.g}" data-line="${i}" data-kind="${kind}"> g</label>${B('×','remove-line','round',`data-index="${i}" data-kind="${kind}" aria-label="${h(p?.name)} eltávolítása"`)}</div>`;}).join('');}
function logMeal(){draft??=state.draft||{name:'',time:'13:40',date,slot:'Ebéd',icon:'ebed',lines:[]};return `${title('ÉTKEZÉS RÖGZÍTÉSE',draft.id?'Pontosítsuk <em>együtt.</em>':'Mi került <em>a tányérodra?</em>','Indulj onnan, ahonnan neked egyszerűbb.')}<div class="source-choices">${B(`${I('kamra',38)}Kamrából`,'pick-pantry','source gold')}${B(`${I('recept',38)}Receptből`,'pick-recipe','source coral')}${B(`${I('mezo',38)}Szöveg / fotó`,'ai-log','source lavender')}</div>
 <form data-form="meal"><div class="form-section">${field('Étkezés neve','name',draft.name,'text','required data-draft="name" placeholder="Például: ebéd a teraszon"')}<div class="two-col">${select('Melyik étkezés?','slot',draft.slot,['Reggeli','Ebéd','Kisétkezés','Vacsora'])}${field('Időpont','time',draft.time,'time','required')}</div>${field('Napló napja','date',draft.date,'date',`required max="${TODAY}"`)}</div>${heading('A tányérodon',B('+ Hozzávaló','pick-pantry','text-btn'))}<div id="draft-lines">${draft.lines.length?lineEditor(draft.lines):'<p class="empty-line">Válassz hozzávalót, receptet vagy adj szöveges leírást.</p>'}</div><div id="draft-totals" class="draft-summary">${statLine(nutrition(draft.lines,state.pantry))}</div><p class="caption">A grammok szabadon javíthatók. Az összegzés együtt változik velük.</p><button class="button full" type="submit">${draft.id?'Módosítás mentése':'Étkezés rögzítése'} ✓</button></form>`;}
function recipeList(){const category=params.get('category')||'Mind';return `${title('A SAJÁT RECEPTTÁRAD','Valami, ami<br><em>jól esne.</em>','Jó ötletek, a te adagodra alakítva.')}<div class="search"><span>⌕</span><input aria-label="Recept keresése" placeholder="Recept, hozzávaló…" data-search="recipes"></div><div class="chips">${['Mind','Reggeli','Ebéd','Vacsora','Kedvencek'].map(c=>link(c,'recipes?category='+encodeURIComponent(c),'chip '+(c===category?'selected':''))).join('')}</div><div class="recipe-grid">${state.recipes.filter(r=>category==='Mind'||r.category===category||category==='Kedvencek'&&r.favorite).map(r=>{const t=nutrition(portionLines(r),state.pantry);return `<button class="recipe-card" data-go="recipe?id=${r.id}" data-searchable="${h(r.name.toLowerCase())}"><div class="recipe-art ${r.icon}">${I(r.icon,100)}<span>${r.minutes} perc</span>${r.favorite?'<b>♥</b>':''}</div><div class="recipe-card-copy"><span class="eyebrow">${h(r.category)}</span><h2>${h(r.name)}</h2><p>${n(t.kcal)} kcal <span>· ${n(t.p)} g fehérje</span></p></div></button>`;}).join('')}</div><p class="search-empty" hidden>Nincs ilyen recept a mintatárban.</p>${B('+ Saját recept','new-recipe','button full')}${row('muhely','Receptműhely','Egy ötletből közösen alakított recept','workshop')}`;}
function recipeDetail(){const r=getRecipe();if(!r)return missing();const lines=portionLines(r,portion),t=nutrition(lines,state.pantry);return `${title(h(r.category).toUpperCase()+' · '+r.minutes+' PERC',h(r.name),h(r.description))}<div class="recipe-cover ${r.icon}">${I(r.icon,142)}${B(r.favorite?'♥':'♡','favorite','round',`aria-label="Kedvenc recept kapcsolása"`)}</div><div class="portion"><span>Az én adagom</span>${B('−','portion-down','round','aria-label="Kevesebb adag"')}<strong>${n(portion,1)}</strong>${B('+','portion-up','round','aria-label="Több adag"')}</div>${statLine(t)}${macros(t)}<div class="action-pair">${B('Ezt ettem','log-recipe','button')}${link('Elkészítem','cook?id='+r.id,'button secondary')}</div>${heading('Hozzávalók',B('Szerkesztés','edit-recipe','text-btn'))}${lines.map(l=>{let p=state.pantry.find(x=>x.id===l.id);return row(p.icon,h(p.name),`${n(l.g)} g · ${p.stock>=l.g?'megvan otthon':n(l.g-p.stock)+' g hiányzik'}`,'item?id='+p.id);}).join('')}${B('Hiányzók a bevásárlólistára','shortages','button secondary full')}${heading('Így készül')}<ol class="recipe-steps">${r.steps.map(s=>`<li>${h(s)}</li>`).join('')}</ol>${row('muhely','Alakítsuk a receptet','Mennyiségek és hozzávalók a Műhelyben','workshop?id='+r.id)}<p class="demo-note">Saját mintarecept · a tápértékek szerkeszthető mintaadatokból számolva.</p>`;}
function recipeEdit(){recipeDraft??=clone(getRecipe()||{id:'',name:'',description:'',servings:1,minutes:20,category:'Ebéd',icon:'ebed',lines:[],steps:['']});const r=recipeDraft;return `${title('SAJÁT RECEPT',r.id?'A te ízlésedre.':'Egy új <em>kedvenc.</em>')}<form data-form="recipe">${field('Recept neve','name',r.name,'text','required data-recipe="name"')}${field('Rövid leírás','description',r.description,'text','data-recipe="description"')}<div class="two-col">${field('Összes adag','servings',r.servings,'number','required min="1" max="20" data-recipe="servings"')}${field('Elkészítés · perc','minutes',r.minutes,'number','required min="1" max="600" data-recipe="minutes"')}</div>${select('Étkezés','category',r.category,['Reggeli','Ebéd','Kisétkezés','Vacsora'])}${heading('Hozzávalók · teljes recept',B('+ Hozzáadok','recipe-pantry','text-btn'))}${lineEditor(r.lines,'recipe')}<label class="field">Elkészítés · lépésenként új sor<textarea name="steps" rows="5" required data-recipe="steps">${h(r.steps.join('\n'))}</textarea></label><button class="button full" type="submit">Recept mentése ✓</button></form>`;}
function workshop(){const r=getRecipe();return `${title('RECEPTMŰHELY','Egy ötlet.<br><em>A te változatod.</em>',r?'Kiindulás: '+h(r.name):'Indulj egy kívánságból vagy a kamrádból.')}<div class="workshop-scene">${I('muhely',100)}<span class="orbit-line"></span>${orb('lavender')}</div><div class="companion-note">${orb('lavender')}<div><strong>Milyen étkezést rakjunk össze?</strong><p>Válassz irányt, vagy írd le a saját ötleted.</p></div></div><div class="chips">${['Fehérjedús','Gyors ebéd','Edzés után','Kamrából'].map(s=>B(s,'workshop-prompt','chip',`data-prompt="${s}"`)).join('')}</div><form data-form="workshop"><label class="field">Az ötleted<textarea name="prompt" required rows="3" placeholder="Egy gyors ebédet szeretnék csirkével…"></textarea></label><button class="button full">Receptvázlat készítése ✧</button></form><p class="demo-note">A Műhely itt előre összeállított mintareceptet készít. A vázlatot mentés előtt szabadon módosíthatod.</p>`;}
function cook(){const r=getRecipe();if(!r)return missing();cookStep=Math.min(cookStep,r.steps.length-1);return `${title('FŐZÉS / '+(cookStep+1)+'. LÉPÉS',h(r.name))}<div class="cook-progress">${r.steps.map((_,i)=>`<i class="${i<=cookStep?'on':''}"></i>`).join('')}</div><div class="cook-scene">${I(r.icon,130)}<span>${cookStep+1}<small> / ${r.steps.length}</small></span></div><h2 class="cook-instruction">${h(r.steps[cookStep])}</h2><p class="caption">${n(portion,1)} adag · a rögzítésnél még módosíthatod.</p><div class="action-pair">${B('Előző','cook-prev','button secondary',cookStep===0?'disabled':'')}${B(cookStep===r.steps.length-1?'Kész · ezt ettem':'Következő →',cookStep===r.steps.length-1?'log-recipe':'cook-next','button')}</div>`;}
function pantryList(){const category=params.get('category')||'Mind';return `${title('AMI OTTHON VAN','A konyhád<br><em>jó alapjai.</em>',`${state.pantry.length} alapanyag · a receptekkel összekapcsolva`)}<div class="search"><span>⌕</span><input aria-label="Keresés a kamrában" placeholder="Alapanyag vagy márka…" data-search="pantry"></div><div class="chips">${['Mind','Fehérje','Gabona','Zöldség','Gyümölcs'].map(c=>link(c,'pantry?category='+encodeURIComponent(c),'chip '+(c===category?'selected':''))).join('')}</div><div class="pantry-list">${state.pantry.filter(p=>category==='Mind'||p.category===category).map(p=>`<div data-searchable="${h((p.name+' '+p.brand).toLowerCase())}">${row(p.icon,h(p.name),h(p.brand)+' · '+n(p.kcal)+' kcal / 100 g','item?id='+p.id,n(p.stock)+' g')}</div>`).join('')}</div><p class="search-empty" hidden>Nincs ilyen tétel a kamrában.</p>${B('+ Új alapanyag','new-item','button full')}${row('tudas','Közös katalógus','Válogass a mintakatalógusból','catalog')}${row('kamra','Importálás','Link, címke vagy fotó alapján','import')}${row('polc','Bevásárlólista',state.shopping.filter(l=>!l.done).length+' tétel vár beszerzésre','shopping')}`;}
function item(){const p=state.pantry.find(x=>x.id===params.get('id'));if(!p)return missing();return `${title(h(p.category).toUpperCase(),h(p.name),h(p.brand))}<div class="dish-hero gold">${I(p.icon,104)}<span>${n(p.stock)}<small> g otthon</small></span></div>${heading('Tápértékek','<small>100 g-ban</small>')}${statLine(p)}${macros(p)}<div class="detail-pairs"><span>Adatforrás<b>${h(p.source)}</b></span><span>Feldolgozottság<b>NOVA ${p.nova}</b></span></div><div class="action-pair">${B('Ezt ettem','log-item','button')}${link('Szerkesztés','item-edit?id='+p.id,'button secondary')}</div>${heading('Receptekben')}${state.recipes.filter(r=>r.lines.some(l=>l.id===p.id)).map(r=>row(r.icon,h(r.name),r.minutes+' perc','recipe?id='+r.id)).join('')||'<p class="caption">Még nincs recepthez kapcsolva.</p>'}<p class="demo-note">A mintakamra saját, szabadon szerkeszthető adatokat tartalmaz.</p>`;}
function itemEdit(){const p=state.pantry.find(x=>x.id===params.get('id'))||pendingItem||{name:'',brand:'Saját',category:'Zöldség',kcal:0,p:0,c:0,f:0,fiber:0,stock:100};return `${title('KAMRA',p.id?'Pontosítsd <em>az alapokat.</em>':'Új alapanyag.')}<form data-form="item">${field('Megnevezés','name',p.name,'text','required')}${field('Márka / megjegyzés','brand',p.brand)}${select('Kategória','category',p.category,['Fehérje','Gabona','Zöldség','Gyümölcs','Tejtermék','Magvak'])}${field('Otthon · gramm','stock',p.stock,'number','required min="0" max="100000"')}${heading('Tápértékek 100 g-ban')}<div class="two-col">${[['kcal','Energia · kcal'],['p','Fehérje · g'],['c','Szénhidrát · g'],['f','Zsír · g'],['fiber','Rost · g']].map(([k,l])=>field(l,k,p[k],'number','required min="0" max="1000" step="0.1"')).join('')}</div><button class="button full">Alapanyag mentése ✓</button></form>`;}
function catalog(){return `${title('KÖZÖS KATALÓGUS','Bővítsd <em>a kamrádat.</em>','A prototípus három szerkeszthető mintatételt kínál.')}${[{name:'Tojás',kcal:155,p:13,c:1.1,f:11},{name:'Túró',kcal:120,p:18,c:3,f:4},{name:'Édesburgonya',kcal:86,p:1.6,c:20,f:0.1}].map((p,i)=>`<div class="catalog-row">${I('kamra',40)}<div><strong>${p.name}</strong><small>${p.kcal} kcal · ${p.p} g fehérje / 100 g</small></div>${B('+','catalog-add','round',`data-index="${i}" aria-label="${p.name} hozzáadása"`)}</div>`).join('')}`;}
function importPage(){return `${title('KAMRA / IMPORT','A címkétől<br><em>a kamrádig.</em>','Először ellenőrzünk, utána mentünk.')}<div class="source-choices">${B(`${I('tudas',40)}Link`,'import-type','source sage','data-type="link"')}${B(`${I('kamra',40)}Címke`,'import-type','source gold','data-type="címke"')}${B(`${I('mezo',40)}Fotó`,'import-type','source lavender','data-type="fotó"')}</div><form data-form="import"><label class="field">Terméknév vagy link<input name="source" placeholder="Például: natúr túró" required></label><button class="button full">Mintaadatok előnézete →</button></form><p class="demo-note">Ez az importálás vizuális próbája. Nincs feltöltés vagy külső lekérés; az előnézet egy jelölt mintatétel, amit mentés előtt ellenőrizhetsz.</p>`;}
function shopping(){return `${title('BEVÁSÁRLÓLISTA','Ami még<br><em>jól jönne.</em>','A receptek hiányzó hozzávalói egy helyen.')}${state.shopping.length?state.shopping.map(l=>{const p=state.pantry.find(p=>p.id===l.id);return `<div class="shopping-row"><label><input type="checkbox" data-shopping="${l.id}" ${l.done?'checked':''}><span>${h(p?.name)}<small>${n(l.g)} g</small></span></label>${B('×','shopping-remove','round',`data-id="${l.id}" aria-label="Tétel eltávolítása"`)}</div>`;}).join(''):empty('Most minden megvan.',link('Nézzük a recepteket','recipes','button secondary'))}<p class="caption">A pipa a lista állapotát jelöli. A kamrakészletet az alapanyag adatlapján tudod módosítani.</p>`;}
function stackRow(s,edit=false){return `<div class="stack-row ${s.taken.includes(date)?'done':''}">${edit?I('stack',36):`<button class="intake-check" aria-label="${h(s.name)} bevételének kapcsolása" aria-pressed="${s.taken.includes(date)}" data-action="intake" data-id="${s.id}">${s.taken.includes(date)?'✓':''}</button>`}<button class="stack-name" data-go="stack-item?id=${s.id}"><strong>${h(s.name)}</strong><small>${h(s.dose)} · ${h(s.zone)}</small></button><span>${h(s.time)}<small>↗</small></span></div>`;}
function stack(){const done=state.stack.filter(s=>s.taken.includes(date)).length,next=state.stack.find(s=>!s.taken.includes(date));return `${title('KIEGÉSZÍTŐK','A saját <em>ritmusod.</em>','A napi bevétel és a protokollod egy helyen.')}<div class="stack-next"><div><p class="eyebrow">${next?'KÖVETKEZŐ · '+h(next.time):'MÁRA RENDBEN'}</p><h2>${h(next?.name||'Szép ritmus.')}</h2><p>${h(next?.dose||'Minden rögzített bevétel megvan.')}</p>${next?B('Bevettem ✓','intake','button',`data-id="${next.id}"`):''}</div>${I('stack',98)}</div><div class="stack-status"><span>${done} / ${state.stack.length} bevétel</span><div class="track"><i style="width:${state.stack.length?done/state.stack.length*100:0}%"></i></div><span>${date===TODAY?'Ma':dateLabel(date)}</span></div>${heading('A napod ritmusa',link('Teljes nap ↗','stack-today'))}${state.stack.map(s=>stackRow(s)).join('')}${row('stack','A protokollom','Tételek, mennyiségek és indoklás','protocol')}${row('idozito','Időzítés','Mikor, mihez kapcsolódik','timing')}${row('recept','Étkezési kapcsolatok','A ritmusod és az étkezések','matches')}${row('injekcio','Gyógyszernapló',state.medications.length?'Saját tételek és bevételek':'Nincs aktív tétel','medications')}${B('+ Új kiegészítő','new-stack','button secondary full')}<p class="demo-note">Előre megadott mintaprotokoll; nem szedési javaslat.</p>`;}
function protocol(){return `${title('A PROTOKOLLOD','Ami a napodhoz<br><em>kapcsolódik.</em>','A napi pipálástól külön szerkeszthető rend.')}${state.stack.map(s=>`<div class="protocol-block">${stackRow(s,true)}<p>${h(s.reason)}</p></div>`).join('')}${B('+ Új kiegészítő','new-stack','button full')}${row('idozito','Időzítés áttekintése','A napi elosztás egy íven','timing')}`;}
function stackToday(){return `${title('STACK / MAI NAP','Egy nap.<br><em>A saját rendjében.</em>')}${dayPicker()}<div class="timeline">${[...state.stack].sort((a,b)=>a.time.localeCompare(b.time)).map(s=>`<div class="timeline-stop"><span>${h(s.time)}</span><div>${stackRow(s)}<p>${h(s.reason)}</p></div></div>`).join('')}</div>${row('beallitas','A protokoll szerkesztése','A tartós beállítások itt változnak','protocol')}`;}
function timing(){return `${title('STACK / IDŐZÍTÉS','Mindennek<br><em>megvan a helye.</em>','Koppints egy tételre az időpont és a kapcsolat módosításához.')}<div class="rhythm-arc">${['Reggel','Délután','Este'].map((v,i)=>`<span style="--arc-y:${i===1?-25:0}px">${I(['reggeli','nap','hold'][i],36)}<b>${v}</b></span>`).join('')}</div>${state.stack.map(s=>stackRow(s,true)).join('')}${row('recept','Étkezésekhez kapcsolva','A mentett horgonyok áttekintése','matches')}`;}
function matches(){return `${title('STACK / ÉTKEZÉSEK','A részletek<br><em>találkoznak.</em>','A mentett időzítést mutatjuk, nem új szedési javaslatot.')} ${state.slots.map((slot,i)=>{const matches=state.stack.filter(s=>s.zone.toLowerCase().includes(slot.name.toLowerCase()));return `<section class="meal-match"><div>${I(['reggeli','ebed','snack','vacsora'][i],44)}<h2>${slot.name}<small>${slot.time}</small></h2></div>${matches.length?matches.map(s=>stackRow(s,true)).join(''):'<p>Nincs ide kapcsolt tétel.</p>'}</section>`;}).join('')}${row('idozito','Időzítés módosítása','A tétel adatlapjáról','timing')}`;}
function stackItem(){const s=state.stack.find(s=>s.id===params.get('id'))||{name:'',dose:'',time:'08:00',zone:'Reggelihez',reason:'Saját beállítás.',taken:[]};return `${title('PROTOKOLL / TÉTEL',s.id?h(s.name):'Új <em>kiegészítő.</em>')}<form data-form="stack">${field('Név','name',s.name,'text','required')}${field('Saját adag / mennyiség','dose',s.dose,'text','required placeholder="A saját protokollod szerinti mennyiség"')}<div class="two-col">${field('Időpont','time',s.time,'time','required')}${select('Kapcsolódás','zone',s.zone,['Reggelihez','Ebédhez','Délután','Vacsorához','Este','Szabad időpont'])}</div>${field('Saját megjegyzés','reason',s.reason)}<button class="button full">Tétel mentése ✓</button></form>${s.id?B('Eltávolítás a protokollból','delete-stack','text-btn danger','data-id="'+s.id+'"'):''}<p class="demo-note">A prototípus a kézi szerkesztést szemlélteti. Nem ajánl készítményt vagy dózist.</p>`;}
function medications(){return `${title('GYÓGYSZERNAPLÓ','Amit számon<br><em>szeretnél tartani.</em>')}${state.medications.length?state.medications.map(s=>`<div class="medication-card"><div>${I('injekcio',45)}<h2>${h(s.name)}</h2>${B('Szerkesztés','edit-med','text-btn',`data-id="${s.id}"`)}</div><p>${h(s.dose)} · ${h(s.time)} · ${s.active?'Aktív':'Szünetel'}</p>${s.active?B(s.logs.includes(date)?'Ma rögzítve ✓':'Bevétel rögzítése','med-intake','button secondary',`data-id="${s.id}"`):''}<small>${s.logs.length} rögzített nap</small>${B(s.active?'Szüneteltetés':'Újra aktív','med-toggle','text-btn',`data-id="${s.id}"`)}</div>`).join(''):empty('Nincs aktív gyógyszered.','<p>A saját gyógyszernaplódat itt tudod felvenni.</p>')}${B('+ Saját tétel','new-med','button full')}`;}
function settings(){const s=state.settings;return `${title('BEÁLLÍTÁSOK','Ahogy neked<br><em>jól működik.</em>','A céljaid és a napodhoz illő ritmus.')}<div class="settings-summary">${I('fuel',68)}<div><span class="eyebrow">A JELENLEGI KERETED</span><strong>${n(target(state))}<small> kcal</small></strong><p>${h(s.profile)}</p></div></div>${row('cel','Keret és makrók',`${s.p} g fehérje · ${s.c} g szénhidrát · ${s.f} g zsír`,'settings-goals')}${row('idozito','Napi ritmus',s.meals+' étkezés · koffein '+s.cutoff+'-ig','settings-rhythm')}${row('heti','Heti étkezési terv','Étkezési ötletek a napjaidhoz','plan')}${row('reggeli','Étkezési ablakok','Időpontok és keretelosztás','slots')}${row('viz','Víz és rost',n(s.water/1000,1)+' l · '+s.fiber+' g','settings-goals')}${row('injekcio','Gyógyszernapló','Saját tételek és bevételek','medications')}<div class="companion-note">${orb()}<div><strong>A ritmus segít, nem korlátoz.</strong><p>Az étkezést más időpontban és utólag is rögzítheted.</p></div></div>${B('Mintanap újraindítása','reset','text-btn')}<p class="demo-note">Csak ennek a külön prototípusnak a helyi adatai változnak.</p>`;}
function goals(){const s=state.settings;return `${title('KERET ÉS MAKRÓK','A számok<br><em>a te oldaladon.</em>')}<form data-form="goals"><div class="form-section"><h2>Napi energia</h2>${field('Alapkeret · kcal','base',s.base,'number','required min="500" max="10000"')}${field('Mozgás · kcal','movement',s.movement,'number','required min="0" max="5000"')}${field('Cél módosítása · kcal','balance',s.balance,'number','required min="-1000" max="2000"')}</div>${select('Makróprofil','profile',s.profile,['Kiegyensúlyozott','Fehérjehangsúlyos','Egyéni'])}<div class="two-col">${[['p','Fehérje · g'],['c','Szénhidrát · g'],['f','Zsír · g'],['fiber','Rost · g'],['water','Víz · ml']].map(([k,l])=>field(l,k,s[k],'number','required min="1" max="10000"')).join('')}</div><p class="caption">A minta céljai kézzel szerkeszthetők. Ez nem a valódi célmotor számítása.</p><button class="button full">Beállítások mentése ✓</button></form>`;}
function rhythm(){const s=state.settings;return `${title('NAPI RITMUS','Legyen helye<br><em>a szüneteknek.</em>')}<div class="rhythm-arc">${state.slots.map((s,i)=>`<span style="--arc-y:${i===1||i===2?-20:0}px">${I(['reggeli','ebed','snack','vacsora'][i],38)}<b>${s.time}</b></span>`).join('')}</div><form data-form="rhythm">${field('Étkezések naponta','meals',s.meals,'number','required min="3" max="6"')}${field('Koffein időhatár','cutoff',s.cutoff,'time','required')}<button class="button full">Ritmus mentése ✓</button></form>${row('reggeli','Az ablakok részletesen','Időpontok és elosztás','slots')}`;}
function slots(){return `${title('ÉTKEZÉSI ABLAKOK','A napodnak<br><em>saját íve van.</em>','Az időpontok irányt adnak. Utólag is rögzíthetsz.')}<form data-form="slots">${state.slots.map((s,i)=>`<div class="slot-edit"><div>${I(['reggeli','ebed','snack','vacsora'][i%4],38)}<h2>${h(s.name)}</h2></div><div class="two-col">${field('Időpont','time'+i,s.time,'time','required')}${field('Napi keret · %','share'+i,s.share,'number','required min="0" max="100"')}</div></div>`).join('')}<p class="caption">Az arányok összege 100%. Ez a kézzel szerkeszthető mintanap ritmusa.</p><button class="button full">Ablakok mentése ✓</button></form>`;}
function plan(){return `${title('HETI ÉTKEZÉSI TERV','Egy kis előrelátás.<br><em>Több szabadság.</em>')}${dayPicker()}<p class="caption">A napválasztóval a mintahét végéig előre tervezhetsz. A tervbe mentés nem jelent elfogyasztott étkezést.</p><form data-form="plan">${state.slots.map((s,i)=>`<div class="plan-slot"><div>${I(['reggeli','ebed','snack','vacsora'][i%4],42)}<h2>${h(s.name)}<small>${h(s.time)}</small></h2></div><label class="field">Receptötlet<select name="slot${i}"><option value="">Még nyitva hagyom</option>${state.recipes.map(r=>`<option value="${r.id}" ${state.plan[date]?.[i]===r.id?'selected':''}>${h(r.name)}</option>`).join('')}</select></label></div>`).join('')}<button class="button full">Terv mentése ✓</button></form>${row('idozito','Étkezési ablakok','A napi időpontok szerkesztése','slots')}`;}
function movement(){return `${title('A NAPOD KAPCSOLATAI','A mozgásod<br><em>itt is számít.</em>')}<div class="dish-hero coral">${I('edzes',110)}<span>17:30<small> · mintanap</small></span></div><h2>Teljes test A</h2><p>A napi keret mozgásrésze most ${n(state.settings.movement)} kcal. Kipróbálhatod, hogyan változik az áttekintés, ha ezt átállítod.</p>${B(state.settings.movement?'A mai mozgás elmarad':'Mozgás visszaállítása','movement-toggle','button full')}${link('Vissza a napi kerethez','energy','button secondary full')}`;}
const pages={diary,week,energy,meal:mealDetail,score,log:logMeal,recipes:recipeList,recipe:recipeDetail,'recipe-edit':recipeEdit,workshop,cook,pantry:pantryList,item,'item-edit':itemEdit,catalog,import:importPage,shopping,stack,protocol,'stack-today':stackToday,timing,matches,'stack-item':stackItem,medications,settings,'settings-goals':goals,'settings-rhythm':rhythm,slots,plan,movement};
const families={diary:['diary','week','energy','meal','score','log','movement'],recipes:['recipes','recipe','recipe-edit','workshop','cook'],pantry:['pantry','item','item-edit','catalog','import','shopping'],stack:['stack','protocol','stack-today','timing','matches','stack-item','medications'],settings:['settings','settings-goals','settings-rhythm','slots','plan']};
const parents={week:'diary',energy:'diary',meal:'diary',score:'meal',log:'diary',recipe:'recipes','recipe-edit':'recipes',workshop:'recipes',cook:'recipe',item:'pantry','item-edit':'pantry',catalog:'pantry',import:'pantry',shopping:'pantry',protocol:'stack','stack-today':'stack',timing:'stack',matches:'stack','stack-item':'protocol',medications:'stack','settings-goals':'settings','settings-rhythm':'settings',slots:'settings',plan:'settings',movement:'energy'};
function render(){const [path,query='']=(location.hash.slice(1)||'diary').split('?');route=path;if(route!=='plan'&&date>TODAY)date=TODAY;params=new URLSearchParams(query);if(params.has('date')&&/^2026-09-(0[2-9]|1[0-3])$/.test(params.get('date'))&&(route==='plan'||params.get('date')<=TODAY))date=params.get('date');lastTab=Object.keys(families).find(k=>families[k].includes(route))||'diary';
 const isTop=NAV.some(([k])=>k===route);document.querySelector('#header').innerHTML=`<div>${isTop?'<a class="wordmark" href="#diary">mezo<span> táplálás.</span></a>':B('‹','back','round back','aria-label="Vissza az előző oldalra"')+'<span class="header-place">'+NAV.find(([k])=>k===lastTab)?.[1]+'</span>'}</div>${B(I('mezo',21)+' Beszélgessünk','chat','header-chat')}`;
 main.innerHTML=(pages[route]||diary)();const search=main.querySelector('[data-search]');if(search&&searchTerms.has(location.hash)){search.value=searchTerms.get(location.hash);const q=search.value.toLocaleLowerCase('hu-HU');let count=0;main.querySelectorAll('[data-searchable]').forEach(el=>{el.hidden=!el.dataset.searchable.includes(q);if(!el.hidden)count++;});main.querySelector('.search-empty').hidden=!!count;}document.querySelector('#dock').innerHTML=`${B(orb('sage')+'<small>Tereim⌄</small>','roles','area-switch','aria-label="Színes mezo területváltó" aria-haspopup="dialog"')}${NAV.map(([key,label,icon])=>`<button data-go="${key}" class="dock-item ${lastTab===key?'active':''}" aria-label="${label}" ${lastTab===key?'aria-current="page"':''}>${I(icon,30)}<span>${label}</span></button>`).join('')}`;
 document.querySelector('#map').innerHTML=NAV.map(([key,label,icon],i)=>`<button class="map-link ${lastTab===key?'active':''}" data-go="${key}">${I(icon,36)}<span><b>${label}</b><small>${['Napi keret, étkezések, AI score','Ötletből saját recept','A hozzávalók és kapcsolataik','Napi bevétel és protokoll','Célok, terv és ritmus'][i]}</small></span></button>`).join('');
 document.title='Mezo · '+(NAV.find(([k])=>k===lastTab)?.[1]||'Táplálás');
}
let priorHash=location.hash;
window.addEventListener('hashchange',()=>{const next=location.hash;scrolls.set(priorHash,main.scrollTop);contextDates.set(priorHash,date);date=contextDates.get(next)??date;if(next.split('?')[0]==='#recipes'){portion=1;cookStep=0;}render();main.scrollTop=scrolls.get(location.hash)||0;main.focus({preventScroll:true});priorHash=next;});
function openModal(titleText,body,cls=''){dialog.className=cls;dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${titleText}</h2>${B('×','close','round','aria-label="Bezárás"')}</div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function picker(kind='meal'){openModal('A kamrádból',`<p class="caption">Több hozzávalót is választhatsz.</p><div class="picker">${state.pantry.map(p=>`<button data-action="pick-item" data-id="${p.id}" data-kind="${kind}">${I(p.icon,36)}<span><strong>${h(p.name)}</strong><small>${n(p.kcal)} kcal / 100 g</small></span><b>+</b></button>`).join('')}</div>${B('A tányéromhoz →','picker-done','button full')}`);}
function chat(){openModal('Beszélgessünk',`<p class="caption">Közös beszélgetés · szemléltető válaszok</p><div class="chat-messages"><div class="chat-bubble companion">${orb('sage')}<p>Itt vagyok. A ${NAV.find(([k])=>k===lastTab)?.[1].toLowerCase()} oldalról érkeztél. Nézzük meg együtt, ami most fontos.</p></div>${state.chat.map(m=>`<div class="chat-bubble ${m.role}">${h(m.text)}</div>`).join('')}</div><form data-form="chat"><label class="field"><span class="sr-only">Üzeneted</span><textarea name="message" required placeholder="Mi jár a fejedben?" rows="2">${h(state.chatDraft||'')}</textarea></label><button class="button full">Elküldöm ↑</button></form>`,'chat-dialog');}
function medForm(id){const s=state.medications.find(m=>m.id===id)||{name:'',dose:'',time:'08:00'};openModal(s.id?'Tétel szerkesztése':'Saját gyógyszernapló',`<form data-form="med" data-id="${s.id||''}">${field('Megnevezés','name',s.name,'text','required')}${field('Saját előírt mennyiség','dose',s.dose,'text','required')}${field('Időpont','time',s.time,'time','required')}<button class="button full">Mentés ✓</button></form>`);}
let pendingItem=null;
document.addEventListener('click',event=>{
 const b=event.target.closest('[data-go],[data-action]');if(!b||b.disabled)return;if(b.dataset.go){go(b.dataset.go);return;}const a=b.dataset.action;
 if(a==='close'){dialog.close();return;}
 if(a==='back'){if(history.state?.fuelLab&&history.state.from){history.back();return;}const p=parents[route]||lastTab;go(p+(params.get('id')&&['recipe','meal'].includes(p)?'?id='+params.get('id'):''));return;}
 if(a==='day-prev'||a==='day-next'){const d=shiftDate(date,a==='day-prev'?-1:1);if(d<'2026-09-02'||d>(route==='plan'?'2026-09-13':TODAY))return;date=d;render();return;}
 if(a==='select-day'){date=b.dataset.date;go('diary?date='+date);return;}
 if(a==='new-meal'){startMeal();return;}
 if(a==='edit-meal'){const m=getMeal();if(m){draft=clone(m);state.draft=draft;persist();go('log');}return;}
 if(a==='delete-meal'){const m=getMeal();openModal('Étkezés törlése',`<p>Csak a „${h(m.name)}” naplóbejegyzést távolítjuk el. A recept és a kamra megmarad.</p>${B('Étkezés törlése','confirm-delete-meal','button full',`data-id="${m.id}"`)}`);return;}
 if(a==='confirm-delete-meal'){const saved=clone(state.meals.find(m=>m.id===b.dataset.id));state.meals=state.meals.filter(m=>m.id!==saved.id);persist();go('diary');notify('Étkezés eltávolítva.',()=>{state.meals.push(saved);persist();render();});return;}
 if(a==='pick-pantry'||a==='recipe-pantry'){picker(a==='recipe-pantry'?'recipe':'meal');return;}
 if(a==='pick-item'){const list=b.dataset.kind==='recipe'?recipeDraft.lines:draft.lines;const old=list.find(l=>l.id===b.dataset.id);if(old)old.g+=100;else list.push({id:b.dataset.id,g:100});b.querySelector('b').textContent='✓';state.draft=draft;persist();return;}
 if(a==='picker-done'){dialog.close();render();return;}
 if(a==='remove-line'){const list=b.dataset.kind==='recipe'?recipeDraft.lines:draft.lines;list.splice(Number(b.dataset.index),1);state.draft=draft;persist();render();return;}
 if(a==='pick-recipe'){openModal('Receptből a tányérodra',state.recipes.map(r=>`<button class="nav-row" data-action="pick-recipe-item" data-id="${r.id}">${I(r.icon,42)}<span><strong>${h(r.name)}</strong><small>Egy adag · javítható mennyiségek</small></span><b>+</b></button>`).join(''));return;}
 if(a==='pick-recipe-item'){const r=state.recipes.find(r=>r.id===b.dataset.id);draft.lines.push(...portionLines(r));if(!draft.name)draft.name=r.name;draft.slot=r.category;draft.icon=r.icon;draft.source='Recept';state.draft=draft;persist();dialog.close();render();return;}
 if(a==='ai-log'){openModal('Mondd el, mit ettél.',`<form data-form="ai-log"><label class="field">Leírás<textarea name="text" rows="3" required placeholder="Például: 150 g görög joghurt és 80 g áfonya"></textarea></label><button class="button full">Szöveges minta feldolgozása ✧</button></form><p class="caption">A demó a kamrában szereplő neveket ismeri fel. Nincs valódi AI-kérés.</p>${B(`${I('mezo',26)} Fotópélda kipróbálása`,'photo-demo','button secondary full')}`);return;}
 if(a==='photo-demo'){draft.lines.push({id:'yogurt',g:150},{id:'berries',g:80});draft.name||='Joghurt áfonyával';draft.source='Fotópélda · becslés';state.draft=draft;persist();dialog.close();render();notify('Mintafelismerés hozzáadva. A grammok javíthatók.');return;}
 if(a==='water'){openModal('Egy pohár szünet.',`<div class="water-hero">${I('viz',88)}<h2>${n((state.water[date]||0)/1000,2)} l</h2><p>${dateLabel(date)} · ${n(state.settings.water/1000,1)} l cél</p></div><form data-form="water">${field('Hozzáadott víz · ml','amount',250,'number','required min="1" max="3000"')}<button class="button full">Víz rögzítése ✓</button></form>`);return;}
 if(a==='water-add'){const old=state.water[date]||0,day=date;state.water[day]=old+250;persist();render();notify('250 ml víz rögzítve.',()=>{state.water[day]=old;persist();render();});return;}
 if(a==='favorite'){const r=getRecipe();r.favorite=!r.favorite;persist();render();return;}
 if(a==='portion-up'||a==='portion-down'){portion=Math.max(.5,Math.min(10,portion+(a==='portion-up'?.5:-.5)));render();return;}
 if(a==='log-recipe'){const r=getRecipe();startMeal(portionLines(r,portion),r.name,r.category,'Recept');return;}
 if(a==='log-item'){const p=state.pantry.find(p=>p.id===params.get('id'));startMeal([{id:p.id,g:100}],p.name,'Kisétkezés','Kamra');return;}
 if(a==='new-recipe'||a==='edit-recipe'){recipeDraft=a==='edit-recipe'?clone(getRecipe()):null;go('recipe-edit'+(a==='edit-recipe'?'?id='+getRecipe().id:''));return;}
 if(a==='shortages'){addShortages(state,getRecipe(),portion);persist();go('shopping');return;}
 if(a==='cook-next'||a==='cook-prev'){cookStep+=a==='cook-next'?1:-1;render();return;}
 if(a==='workshop-prompt'){main.querySelector('textarea[name="prompt"]').value=b.dataset.prompt;return;}
 if(a==='new-item'){pendingItem=null;go('item-edit');return;}
 if(a==='catalog-add'){const items=[{name:'Tojás',kcal:155,p:13,c:1.1,f:11},{name:'Túró',kcal:120,p:18,c:3,f:4},{name:'Édesburgonya',kcal:86,p:1.6,c:20,f:.1}],p=items[Number(b.dataset.index)];if(state.pantry.some(i=>i.name===p.name)){notify('Ez a tétel már a kamrádban van.');return;}state.pantry.push({...p,id:uid(),brand:'Mintakatalógus',category:'Fehérje',icon:'kamra',stock:0,unit:'g',fiber:0,nova:1,source:'Katalógusminta'});persist();b.textContent='✓';notify(p.name+' a kamrádba került.');return;}
 if(a==='import-type'){main.querySelector('input[name="source"]').placeholder=b.dataset.type==='link'?'Termékoldal linkje':'A termék neve a '+b.dataset.type+' alapján';notify('A '+b.dataset.type+' import mintafolyamatát próbálod.');return;}
 if(a==='shopping-remove'){state.shopping=state.shopping.filter(l=>l.id!==b.dataset.id);persist();render();return;}
 if(a==='intake'){const id=b.dataset.id,day=date;toggleIntake(state,id,day);persist();render();notify('Bevétel állapota frissítve.',()=>{toggleIntake(state,id,day);persist();render();});return;}
 if(a==='new-stack'){go('stack-item');return;}
 if(a==='delete-stack'){const id=b.dataset.id,saved=clone(state.stack.find(s=>s.id===id));state.stack=state.stack.filter(s=>s.id!==id);persist();go('protocol');notify('Tétel eltávolítva.',()=>{state.stack.push(saved);persist();render();});return;}
 if(a==='new-med'||a==='edit-med'){medForm(b.dataset.id);return;}
 if(a==='med-toggle'||a==='med-intake'){const s=state.medications.find(m=>m.id===b.dataset.id);if(a==='med-toggle')s.active=!s.active;else s.logs=s.logs.includes(date)?s.logs.filter(d=>d!==date):[...s.logs,date];persist();render();notify('Gyógyszernapló frissítve.');return;}
 if(a==='movement-toggle'){state.settings.movement=state.settings.movement?0:350;persist();render();notify('A napi energiakeret frissült.');return;}
 if(a==='chat'){chat();return;}
 if(a==='roles'){openModal('Merre menjünk?',`<p class="eyebrow">UGYANAZ A TÁRS · TÖBBFÉLE TÉR</p><div class="role-options">${[['coral','Otthon','A napod és a közös beszélgetés','home'],['blue','Mozgás','Edzés, sport és regeneráció','train'],['sage','Táplálás','Napló, receptek és a saját ritmusod','fuel'],['lavender','Életem','Ami benned és körülötted történik','life'],['rose','A közös kép','Összefüggések és megfigyelések','insights']].map(([tone,label,sub,id])=>`<button data-action="choose-role" data-role="${id}" data-label="${label}" class="${id==='fuel'?'selected':''}">${orb(tone)}<span><strong>${label}</strong><small>${sub}</small></span>${id==='fuel'?'<b>✓</b>':'<b>↗</b>'}</button>`).join('')}</div><p class="caption">Ebben a külön tanulmányban a Táplálás van kidolgozva.</p>`,'roles-dialog');return;}
 if(a==='choose-role'){if(b.dataset.role==='fuel'){dialog.close();go(lastTab);return;}openModal(b.dataset.label,`${title('A MEZO TEREI','A történeted<br><em>veled marad.</em>')}<p>A többi teret a korábbi Boop prototípusban járhatod be. Itt a Fuel új irányát próbáljuk.</p><a class="button full" href="http://127.0.0.1:5193/?v=boop#presence/home/today" target="_blank" rel="noopener">A Boop prototípus megnyitása ↗</a>${B('Vissza a Tápláláshoz','close','button secondary full')}`);return;}
 if(a==='rescore'){b.disabled=true;b.textContent='A mintaválasz készül…';setTimeout(()=>{if(route==='score')render();notify('Mintanézet frissítve. A demópontszám változatlan.');},650);return;}
 if(a==='undo'){undoAction?.();undoAction=null;document.querySelector('#toast').classList.remove('show');return;}
 if(a==='reset'){openModal('Újrakezdjük a mintanapot?',`<p>Csak ennek a Fuel prototípusnak a mentett próbaadatai állnak vissza. A korábbi Boop prototípus megmarad.</p>${B('Mintanap visszaállítása','confirm-reset','button full')}`);return;}
 if(a==='confirm-reset'){state=createState();draft=null;recipeDraft=null;date=TODAY;persist();dialog.close();go('diary');notify('A mintanap újra készen áll.');}
});
document.addEventListener('input',event=>{const input=event.target;
 if(input.dataset.search){searchTerms.set(location.hash,input.value);const query=input.value.toLocaleLowerCase('hu-HU');let visible=0;main.querySelectorAll('[data-searchable]').forEach(el=>{el.hidden=!el.dataset.searchable.includes(query);if(!el.hidden)visible++;});const note=main.querySelector('.search-empty');if(note)note.hidden=!!visible;}
 if(input.dataset.line!==undefined){const list=input.dataset.kind==='recipe'?recipeDraft?.lines:draft?.lines;const value=Number(input.value);if(list&&Number.isFinite(value))list[Number(input.dataset.line)].g=value;const totals=main.querySelector('#draft-totals');if(totals)totals.innerHTML=statLine(nutrition(draft.lines,state.pantry));state.draft=draft;persist();}
 if(input.dataset.draft){draft[input.dataset.draft]=input.value;state.draft=draft;persist();}
 if(input.dataset.recipe){recipeDraft[input.dataset.recipe]=input.dataset.recipe==='steps'?input.value.split('\n'):input.value;}
 if(input.name==='message'){state.chatDraft=input.value;persist();}
});
document.addEventListener('change',event=>{const input=event.target;
 if(input.id==='date-picker'&&input.value>= '2026-09-02'&&input.value<=(route==='plan'?'2026-09-13':TODAY)){date=input.value;render();}
 if(input.dataset.shopping){const l=state.shopping.find(l=>l.id===input.dataset.shopping);l.done=input.checked;persist();}
 if(input.closest('[data-form="meal"]')&&draft){if(['slot','date','time'].includes(input.name)){draft[input.name]=input.value;state.draft=draft;persist();}}
 if(input.closest('[data-form="recipe"]')&&recipeDraft&&input.name==='category')recipeDraft.category=input.value;
});
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const f=Object.fromEntries(new FormData(form));try{
 switch(form.dataset.form){
 case 'meal':{Object.assign(draft,f);if(draft.date>TODAY)throw Error('Jövőbeli napra a tervben tudsz étkezést felvenni.');draft.icon=({Reggeli:'reggeli',Ebéd:'ebed',Kisétkezés:'snack',Vacsora:'vacsora'})[draft.slot];const m=saveMeal(state,draft);state.draft=null;draft=null;persist();go('meal?id='+m.id);notify('Étkezés rögzítve · a napi számok frissültek.');break;}
 case 'recipe':{if(!recipeDraft.lines.length||recipeDraft.lines.some(l=>l.g<=0))throw Error('Adj legalább egy hozzávalót érvényes mennyiséggel.');const r={...recipeDraft,...f,id:recipeDraft.id||uid(),servings:Number(f.servings),minutes:Number(f.minutes),steps:f.steps.split('\n').filter(Boolean),icon:({Reggeli:'reggeli',Ebéd:'ebed',Kisétkezés:'snack',Vacsora:'vacsora'})[f.category]};const i=state.recipes.findIndex(x=>x.id===r.id);if(i<0)state.recipes.push(r);else state.recipes[i]=r;recipeDraft=null;persist();go('recipe?id='+r.id);notify('A recept a saját táradba került.');break;}
 case 'workshop':{recipeDraft=clone(getRecipe()||state.recipes[0]);recipeDraft.id='';recipeDraft.name+=' · saját változat';recipeDraft.description=f.prompt;go('recipe-edit');notify('Szerkeszthető mintavázlat készült.');break;}
 case 'item':{const old=state.pantry.find(p=>p.id===params.get('id'));const p={...(old||pendingItem||{}),...f,id:old?.id||uid(),icon:old?.icon||'kamra',source:old?.source||pendingItem?.source||'Kézi minta',nova:1,unit:'g'};for(const key of ['kcal','p','c','f','fiber','stock'])p[key]=Number(f[key]);if(old)Object.assign(old,p);else state.pantry.push(p);pendingItem=null;persist();go('item?id='+p.id);notify('A kamratétel mentve.');break;}
 case 'import':{pendingItem={name:'Natúr túró · importminta',brand:f.source,category:'Tejtermék',kcal:120,p:18,c:3,f:4,fiber:0,stock:250,source:'Importminta · ellenőrizendő'};go('item-edit');notify('Mintaadatok · ellenőrizd őket mentés előtt.');break;}
 case 'water':{const day=date,old=state.water[day]||0;state.water[day]=old+Number(f.amount);persist();dialog.close();render();notify(f.amount+' ml víz rögzítve.',()=>{state.water[day]=old;persist();render();});break;}
 case 'ai-log':{const folded=f.text.toLocaleLowerCase('hu-HU').normalize('NFD').replace(/\p{Diacritic}/gu,'');const found=state.pantry.filter(p=>folded.includes(p.name.toLocaleLowerCase('hu-HU').normalize('NFD').replace(/\p{Diacritic}/gu,'')));if(!found.length)throw Error('A demó csak a mintakamra neveit ismeri. Válassz a Kamrából, vagy próbáld: görög joghurt és áfonya.');for(const p of found){const name=p.name.toLocaleLowerCase('hu-HU').normalize('NFD').replace(/\p{Diacritic}/gu,'');const prefix=folded.slice(0,folded.indexOf(name));const grams=prefix.match(/(\d+)\s*g\s*$/);draft.lines.push({id:p.id,g:grams?Number(grams[1]):100});}draft.name||=found.map(p=>p.name).join(' és ');draft.source='Szöveges minta · javítandó becslés';state.draft=draft;persist();dialog.close();render();notify('Mintafelismerés · ellenőrizd a grammokat.');break;}
 case 'stack':{const old=state.stack.find(s=>s.id===params.get('id'));if(old)Object.assign(old,f);else state.stack.push({...f,id:uid(),taken:[]});state.stack.sort((a,b)=>a.time.localeCompare(b.time));persist();go('protocol');notify('Protokoll mentve.');break;}
 case 'med':{const old=state.medications.find(m=>m.id===form.dataset.id);if(old)Object.assign(old,f);else state.medications.push({...f,id:uid(),active:true,logs:[]});persist();dialog.close();render();notify('Saját tétel mentve.');break;}
 case 'goals':{const next={...state.settings};for(const [k,v] of Object.entries(f))next[k]=k==='profile'?v:Number(v);if(next.base+next.movement+next.balance<=0)throw Error('A napi energiakeret legyen pozitív.');state.settings=next;persist();go('settings');notify('A kereted és makrócéljaid frissültek.');break;}
 case 'rhythm':{const oldSlots=clone(state.slots);state.settings.meals=Number(f.meals);state.settings.cutoff=f.cutoff;const count=Number(f.meals),base=480,end=1140;state.slots=Array.from({length:count},(_,i)=>{const minute=Math.round(base+(end-base)*i/(count-1));return {name:i===0?'Reggeli':i===count-1?'Vacsora':i===1?'Ebéd':'Kisétkezés '+(i-1),time:String(Math.floor(minute/60)).padStart(2,'0')+':'+String(minute%60).padStart(2,'0'),share:Math.floor(100/count)+(i<100%count?1:0)};});for(const [d,values] of Object.entries(state.plan))state.plan[d]=state.slots.map(s=>values[oldSlots.findIndex(old=>old.name===s.name)]||'');persist();go('settings');notify('Ritmus mentve · a terv új időpontokat kapott.');break;}
 case 'slots':{const next=state.slots.map((s,i)=>({...s,time:f['time'+i],share:Number(f['share'+i])}));if(Math.abs(next.reduce((a,s)=>a+s.share,0)-100)>.01)throw Error('Az ablakok aránya együtt 100% legyen.');state.slots=next;persist();go('settings');notify('Étkezési ablakok mentve.');break;}
 case 'plan':{state.plan[date]=state.slots.map((_,i)=>f['slot'+i]);persist();notify('Terv mentve · étkezést még nem rögzítettünk.');break;}
 case 'chat':{const t=dayTotals(state,date);state.chat.push({role:'user',text:f.message},{role:'companion',text:`A mintanaplódban ${n(t.kcal)} kcal és ${n(t.p)} g fehérje szerepel. ${n(target(state)-t.kcal)} kcal maradt a keretedből. Az étkezés adatlapján tudjuk pontosítani a mennyiségeket. Ez előre megírt demóválasz, nem AI-tanács.`});state.chatDraft='';persist();chat();dialog.querySelector('.chat-messages').scrollTop=99999;break;}
 }
 }catch(error){notify(error.message);}
});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
render();
